#include <iostream>
#include <vector>

class Example {
  public:
      void run(std::vector<int>& v) {
            for (auto& el : v) {
                  auto *ptr = &el;
                  *ptr += 2;
                  std::cout << el << " ";
            }
      }
};

int main() {
      std::vector<int> values{1, 2, 3};
      Example object;
      object.run(values);
      return 0;
}
